DUT.Declaration:
TYPE ST_EpsonAdsControlHmi :
STRUCT
    sName                      : STRING(255);
    bEnable                    : BOOL;
    bError                     : BOOL;
    eControlSource             : E_ControlSource;
    bCmdReset                  : BOOL;
    bCmdUserReaction           : BOOL;
    eCmdUserReaction           : E_EpsonUserReaction;

    eState                     : E_EpsonAdsControlState;
    bBusy                      : BOOL;
    bDone                      : BOOL;
    bHeartbeatOk               : BOOL;
    bWaferPicked               : BOOL;
    bWaferPlaced               : BOOL;
    bForceReleaseRequest       : BOOL;
    bAdsConnected              : BOOL;
    bStationChannelConnected   : BOOL;
    bRemoteControlConnected    : BOOL;
    bWarning                   : BOOL;
    nErrorCode                 : UINT;
    sErrorText                 : STRING(255);
    sWarningText               : STRING(255);
    nActiveSequence            : UDINT;
    nDoneSequence              : UDINT;
    nErrorSequence             : UDINT;
    nGrantSequence             : UDINT;
    dwRequestMask              : DWORD;
    dwGrantedMask              : DWORD;
    dwHeldMask                 : DWORD;
    dwReleaseMask              : DWORD;
    eProgress                  : E_EpsonProgress;
    eRobotState                : E_EpsonState;
    nCurrentToolType           : E_EpsonTool;
    stPrompt                   : ST_EpsonUserPrompt;
END_STRUCT
END_TYPE
